import React, { Component } from 'react';
import { loginProcedureForLocalStorage, logoutProcedureForLocalStorage } from '../../Utils/AuthRelatedThings';
import { Logger, copyStringToClipboard } from '../../Utils/Utils';
import moment from 'moment';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { Form } from 'react-bootstrap';
import {
    CButton,
    CCard,
    CCardBody,
    CCardGroup,
    CCol,
    CContainer,
    CForm,
    CInput,
    CInputGroup,
    CInputGroupPrepend,
    CInputGroupText,
    CRow,
    CTextarea
  } from '@coreui/react';
import CIcon from '@coreui/icons-react';

const FILE_NAME = "FormattedDateProvider.js";

const __YYYYMMDD_WITH_DASHES__ = 'YYYY-MM-DD';
const __YYYYMMDD_WITH_DASHES_AND_WEEKDAY__ = 'YYYY-MM-DD ddd';
const __YYYYMMDD__ = 'YYYYMMDD';
const __YYYYMMDD_HHmm_WITH_UNDERSCORE__ = 'YYYYMMDD_HHmm';
const __YYYYMMDD_HHmm_WITH_SAPCE__ = 'YYYYMMDD HHmm';
const __UNIVERSAL_DATE_TIME_WITH_SECS_WITH_UNDERSCORE__ = 'YYYYMMDD_HHmmss';
const __UNIVERSAL_DATE_TIME_WITH_SECS__ = 'YYYY-MM-DD HH:mm:ss';
const __YYYYMMDD_WITH_DASHES_WITH_WEEKDAY_AND_TIME_WITH_COLON__ = 'YYYY-MM-DD ddd HH:mm';

const enabledFormats = [
    __YYYYMMDD_WITH_DASHES_AND_WEEKDAY__,
    __YYYYMMDD_WITH_DASHES_WITH_WEEKDAY_AND_TIME_WITH_COLON__,
    __YYYYMMDD_WITH_DASHES__,
    __YYYYMMDD__,
    __YYYYMMDD_HHmm_WITH_UNDERSCORE__,
    __YYYYMMDD_HHmm_WITH_SAPCE__,
    __UNIVERSAL_DATE_TIME_WITH_SECS_WITH_UNDERSCORE__,
    __UNIVERSAL_DATE_TIME_WITH_SECS__
];

const initialState = {
    isLoaded: false,
    currentDateTime: null
}

class FormattedDateProvider extends Component {
    
    constructor(props) {
        super(props);
        this.state = JSON.parse(JSON.stringify(initialState));
    }

    componentDidMount() {
        document.title = "Satanlabs - FormattedDateProvider page";
        this.setState({
            isLoaded: true,
            currentDateTime: this.getCurrentDateTime()
        });
        
        this.updateCurrentDateTime();
    }

    updateCurrentDateTime() {
        setInterval(() => {
            this.setState({
            currentDateTime: this.getCurrentDateTime()
        });
        }, 1000);
    }

    getCurrentDateTime () {
        return new moment().format(__UNIVERSAL_DATE_TIME_WITH_SECS__);
    }

    copyCurrentDateTimeAndNotify_buttonClickEvent = (event, dateTimeFormat) => {
        this.copyCurrentDateTimeAndNotify(dateTimeFormat);
    }

    copyCurrentDateTimeAndNotify = (dateTimeFormat) => {
        const dateTimeInFormat = new moment().format(dateTimeFormat);
        copyStringToClipboard(dateTimeInFormat);
        toast("✅ 📋 COPIED `" + dateTimeInFormat + "` to clipboard !");
    }

    submitCustomDateFormat = (event) => {
        event.preventDefault();
        const dateTimeFormat = event.target.inputDateFormat.value;
        Logger(FILE_NAME, "submitCustomDateFormat", "submitCustomDateFormat", "dateTimeFormat", dateTimeFormat);
        this.copyCurrentDateTimeAndNotify(dateTimeFormat);
    }

    render() {
        Logger(FILE_NAME, "render", "render", "this.state", this.state);

        return (
            <div>
                <br /><br />
                <div style={{justifyContent : "center", alignItems: "center"}}>
                    <h1 style={{
                        color: "rgba(34,34,34,.8)",
                        padding: "10px 20px",
                        margin: "0 0 20px",
                        fontSize: "40px",
                        lineHeight: "60px",
                        borderRadius: "4px",
                        border: "1px solid rgba(34, 34, 34, .3)",
                        backgroundColor : "#61b2a7"
                    }}>
                        Current Date-Time (Local) : '{ this.state.currentDateTime }'
                    </h1>
                </div>

                <table border = '1' style = {{
                    fontSize : "20px"
                }}>
                    <thead>
                        <tr>
                            <th>Date-Time Format</th>
                            <th>Current Date-Time in format</th>
                            <th>actions</th>
                        </tr>
                    </thead>
                    <tbody>
                    {
                        enabledFormats.map((dateTimeFormatString, index) => {
                            return <tr key = {"dateInParticularFormat_" + index}>
                                <td>{dateTimeFormatString}</td>
                                <td>{ new moment().format(dateTimeFormatString) }</td>
                                <td> 
                                    &nbsp; &nbsp;
                                    <button onClick = { (event) => {this.copyCurrentDateTimeAndNotify_buttonClickEvent(event, dateTimeFormatString)} }>
                                        COPY 📋
                                    </button>
                                    &nbsp;&nbsp;
                                </td>
                            </tr>
                        })
                    }
                    </tbody>
                </table>

                <hr/>

                <CContainer>
                    <CRow>
                        <CCol md="5">
                            <CCardGroup>
                                <CCard className="p-4">
                                    <CCardBody>
                                        <CForm onSubmit={this.submitCustomDateFormat}>
                                            <h2>Get date in a custom format</h2>
                                            <br/>
                                            <div>You can go to&nbsp;
                                                <a href='https://momentjs.com/docs/#/displaying/format/' target='_blank'>https://momentjs.com/docs/#/displaying/format/</a>
                                                &nbsp;for guidence around more date-formats.
                                                <br/>
                                                This page uses `momentjs` for date-time formatting.
                                            </div>
                                            <br/>
                                            <CRow>
                                                <CCol xs="6">
                                                    <CInputGroup className="mb-3">
                                                        <CInputGroupPrepend>
                                                            <CInputGroupText>
                                                            <CIcon name="cilPencil" />
                                                            </CInputGroupText>
                                                        </CInputGroupPrepend>
                                                        <CInput
                                                            placeholder="Date format" 
                                                            autoComplete="on"
                                                            type="text"
                                                            step="any"
                                                            id="inputDateFormat"
                                                            label="Date format"
                                                            required
                                                        />
                                                    </CInputGroup>
                                                </CCol>
                                                <CCol>
                                                    <CButton color="success" className="px-4" type='submit'>Generate and copy 📋</CButton>
                                                </CCol>
                                            </CRow>
                                        </CForm>
                                    </CCardBody>
                                </CCard>
                            </CCardGroup>
                        </CCol>
                    </CRow>
                </CContainer>

            {/* // https://momentjs.com/docs/#/displaying/format/ */}

                <ToastContainer
                    position="bottom-center"
                    autoClose={700}
                    hideProgressBar={false}
                    newestOnTop={false}
                    closeOnClick
                    rtl={false}
                    pauseOnFocusLoss
                    draggable
                    pauseOnHover
                    theme="light"
                />
            </div>
        );
    }

}

export default FormattedDateProvider;
